const visual = {
  prepare: function (input) {
    var T = [
      '一元二次方程求根公式',
      '1', 'x²', ' − 4', 'x', ' + 4', ' = 0',
      'a = 1', 'b = −4', 'c = 4',
      'x =',
      '−', 'b', ' ± ', '√', 'b²', ' − 4', 'a', 'c',
      '2', 'a',
      '代入 a = 1，b = −4，c = 4',
      'Δ = b² − 4ac = (−4)² − 4·1·4 = 16 − 16',
      '= 0'
    ];
    return T.map(function (t) { return { kind: 'text', payload: t }; });
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 760;
    var H = (input.viewport && input.viewport.heightDu) || 560;
    var s = Math.min(W / 760, H / 560);
    var ox = (W - 760 * s) / 2;
    var oy = (H - 560 * s) / 2;
    function X(v) { return ox + v * s; }
    function Y(v) { return oy + v * s; }
    function tw(str, size) {
      var w = 0;
      for (var i = 0; i < str.length; i++) {
        var c = str.charCodeAt(i);
        if (c === 32) w += size * 0.33;
        else if (c > 0x2e80) w += size;
        else if (c === 0x2212 || c === 0x00b1 || c === 0x221a || c === 0x00b2 ||
                 c === 0x0394 || c === 0x00b7) w += size * 0.66;
        else w += size * 0.58;
      }
      return w;
    }

    var paths = [];
    var kids = [];
    var pc = 0;

    function addPath(cmds, stroke, sw, fill) {
      var id = 'p' + (pc++);
      paths.push({ id: id, commands: cmds });
      kids.push({ type: 'path', pathId: id, stroke: stroke || '#1f2937', strokeWidth: (sw === undefined ? 1.6 : sw) * s, fill: fill || 'none' });
      return id;
    }
    function line(x1, y1, x2, y2, color, sw) {
      return addPath(visualSdk.polyline([[X(x1), Y(y1)], [X(x2), Y(y2)]]), color, sw);
    }
    function rect(x, y, w, h, color, sw, fill) {
      return addPath(visualSdk.polyline([[X(x), Y(y)], [X(x + w), Y(y)], [X(x + w), Y(y + h)], [X(x), Y(y + h)], [X(x), Y(y)]]), color, sw, fill);
    }
    function dot(cx, cy, r, color) {
      return addPath(visualSdk.circle(X(cx), Y(cy), r * s), color, 1.4, color);
    }
    function label(cx, cy, text, size, color, weight) {
      kids.push({ type: 'label', text: text, x: X(cx), y: Y(cy), fontSize: size * s, fill: color, fontWeight: weight || 'normal', anchor: 'middle' });
    }

    var DARK = '#1f2937', BLUE = '#2563eb', RED = '#dc2626', GREEN = '#059669', PURPLE = '#7c3aed';

    label(380, 46, '一元二次方程求根公式', 24, DARK, 'bold');

    var eqS = 28;
    var eq = [
      { t: '1', c: BLUE },
      { t: 'x²', c: DARK },
      { t: ' − 4', c: RED },
      { t: 'x', c: DARK },
      { t: ' + 4', c: GREEN },
      { t: ' = 0', c: DARK }
    ];
    var total = 0, i;
    for (i = 0; i < eq.length; i++) { eq[i].w = tw(eq[i].t, eqS); total += eq[i].w; }
    var cur = 380 - total / 2;
    for (i = 0; i < eq.length; i++) {
      eq[i].x0 = cur;
      eq[i].x1 = cur + eq[i].w;
      label(cur + eq[i].w / 2, 112, eq[i].t, eqS, eq[i].c, 'bold');
      cur += eq[i].w;
    }

    function bracket(x0, x1, y, color) {
      line(x0, y, x1, y, color, 2.2);
      line(x0, y, x0, y + 7, color, 2.2);
      line(x1, y, x1, y + 7, color, 2.2);
    }
    var cStart = eq[4].x0 + tw(' + ', eqS);
    bracket(eq[0].x0, eq[0].x1, 126, BLUE);
    bracket(eq[2].x0, eq[2].x1, 126, RED);
    bracket(cStart, eq[4].x1, 126, GREEN);

    var leads = [
      { x: (eq[0].x0 + eq[0].x1) / 2, tx: 150, txt: 'a = 1', c: BLUE },
      { x: (eq[2].x0 + eq[2].x1) / 2, tx: 380, txt: 'b = −4', c: RED },
      { x: (cStart + eq[4].x1) / 2, tx: 612, txt: 'c = 4', c: GREEN }
    ];
    for (i = 0; i < leads.length; i++) {
      dot(leads[i].x, 139, 2.6, leads[i].c);
      line(leads[i].x, 139, leads[i].tx, 170, leads[i].c, 1.4);
      label(leads[i].tx, 190, leads[i].txt, 18, leads[i].c, 'bold');
    }

    var fS = 24;
    var numP = [
      { t: '−', c: DARK }, { t: 'b', c: RED }, { t: ' ± ', c: DARK }, { t: '√', c: DARK },
      { t: 'b²', c: RED }, { t: ' − 4', c: DARK }, { t: 'a', c: BLUE }, { t: 'c', c: GREEN }
    ];
    var numW = 0;
    for (i = 0; i < numP.length; i++) { numP[i].w = tw(numP[i].t, fS); numW += numP[i].w; }
    numW += (numP.length - 1) * 1.5;
    var dw1 = tw('2', fS), dw2 = tw('a', fS);
    var denW = dw1 + 1.5 + dw2;
    var fracW = Math.max(numW, denW) + 26;
    var xEqW = tw('x =', fS);
    var groupW = xEqW + 16 + fracW;
    var gx = 380 - groupW / 2;
    var fx = gx + xEqW + 16 + fracW / 2;

    var nBase = 272, barY = 292, dBase = 322;
    label(gx + xEqW / 2, barY, 'x =', fS, DARK, 'bold');

    var nc = fx - numW / 2;
    var radX0 = 0, radX1 = 0;
    for (i = 0; i < numP.length; i++) {
      var w = numP[i].w;
      if (i === 4) radX0 = nc;
      if (i === 7) radX1 = nc + w;
      label(nc + w / 2, nBase, numP[i].t, fS, numP[i].c, 'normal');
      nc += w + 1.5;
    }
    line(radX0 - 5, nBase - fS * 0.92, radX1 + 4, nBase - fS * 0.92, DARK, 2);
    line(fx - fracW / 2, barY, fx + fracW / 2, barY, DARK, 2.2);

    var dstart = fx - denW / 2;
    label(dstart + dw1 / 2, dBase, '2', fS, DARK, 'normal');
    label(dstart + dw1 + 1.5 + dw2 / 2, dBase, 'a', fS, BLUE, 'normal');

    label(380, 392, '代入 a = 1，b = −4，c = 4', 20, '#4b5563', 'normal');

    var main = 'Δ = b² − 4ac = (−4)² − 4·1·4 = 16 − 16';
    var tail = '= 0';
    var mS = 20, tS = 24;
    var wM = tw(main, mS), wT = tw(tail, tS);
    var gap = 14;
    var sx0 = 380 - (wM + gap + wT) / 2;
    label(sx0 + wM / 2, 468, main, mS, DARK, 'normal');
    var bxc = sx0 + wM + gap + wT / 2;
    var bw = wT + 22, bh = 42;
    rect(bxc - bw / 2, 438, bw, bh, PURPLE, 2, '#f5f3ff');
    label(bxc, 468, tail, tS, PURPLE, 'bold');

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: kids }
    };
  }
};
